227|        scene={pic.card.phase === "ready" ? { url: pic.card.url, caption: pic.card.caption } : null}
228|        figures={pic.figures}
229|        onGotoScene={gotoScenePicture}
230|        onGotoFigure={gotoFigure}
231|        onOpen={pic.openLightbox}
232|        pref={pref}
