258|    document.addEventListener("keydown", onKey);
259|    return () => {
260|      document.removeEventListener("mousedown", onDown);
261|      document.removeEventListener("keydown", onKey);
262|    };
263|  }, [popover]);
264|
265|  return {
266|    card,
267|    figures,
268|    popover,
269|    viewRef,
270|    popRef,
271|    illustrateScene,
272|    illustratePassage,
273|    hidePopover,
274|    clearScene,
275|    removeFigure,
276|    retryFigure,
277|    lightbox,
278|    openLightbox,
279|    closeLightbox,
280|  };
