1|// Picture state for one scene: the pane card plus inline figures.
2|// The client sends ordinals and ids only, never text. Session caches
3|// survive sub-page and scene moves, so a shown picture never refetches.
4|//
5|// Ordering rules: one request at a time across scene and figure (a second
6|// request while one is in flight is a silent no-op); retryFigure only
7|// works from the error phase; the caller must call hidePopover on pager
8|// moves. The style pref arrives as a hook argument and is read through a
9|// ref, so the callbacks stay stable when it changes.
10|"use client";
11|
12|import { useCallback, useEffect, useRef, useState } from "react";
13|import { MSG_FAILED, MSG_RETRY } from "@/core/images";
14|import { canIllustrateScene, canRetryFigure, canStart, finish, tryStart } from "./figure-placement";
15|import type { ImageResponse } from "@/core/images";
16|import { requestStyleFields, styleCredit } from "../image-style";
17|import type { ImageStylePref } from "../image-style";
18|import { pickEndN, pickStartN } from "../picture-selection";
19|import type { ParaEntry } from "../picture-selection";
20|
21|export type SceneCard =
22|  | { phase: "idle" }
23|  | { phase: "loading" }
24|  | { phase: "ready"; url: string; caption: string }
25|  | { phase: "error"; message: string };
26|
27|export interface InlineFigure {
28|  id: string;
29|  phase: "loading" | "ready" | "error";
30|  url: string | null;
31|  quote: string;
32|  startN: number;
33|  endN: number;
34|  credit: string;
35|  message: string | null;
36|}
37|
38|export interface LightboxItem {
39|  src: string;
40|  caption: string;
41|}
42|
43|const POLL_MS = 3000;
44|const POLL_MAX = 40;
45|
46|const sceneCache = new Map<string, { url: string; caption: string }>();
47|
48|// Read-only view of the session cache for the panels grid. Never
49|// writes, so it cannot change picture behaviour.
50|export function getCachedScenePicture(sceneId: string): { url: string; caption: string } | null {
51|  const hit = sceneCache.get(sceneId);
52|  return hit ? { url: hit.url, caption: hit.caption } : null;
53|}
54|const figureCache = new Map<string, InlineFigure[]>();
55|let figureSeq = 1;
56|
57|function paraOf(node: Node | null): Element | null {
58|  if (!node) return null;
59|  const el = node.nodeType === Node.TEXT_NODE ? node.parentElement : (node as Element);
60|  return el?.closest?.("p[id]") ?? null;
61|}
62|
63|async function postImage(body: unknown): Promise<ImageResponse> {
64|  const res = await fetch("/api/images", {
65|    method: "POST",
66|    headers: { "Content-Type": "application/json" },
67|    body: JSON.stringify(body),
68|  });
69|  return (await res.json()) as ImageResponse;
70|}
71|
72|async function poll(body: unknown): Promise<{ url: string; caption: string }> {
73|  let left = POLL_MAX;
74|  for (;;) {
75|    let res: ImageResponse;
76|    try {
77|      res = await postImage(body);
78|    } catch {
79|      throw new Error(MSG_FAILED);
80|    }
81|    if (res.status === "ready") return { url: res.url, caption: res.caption };
82|    if (res.status === "error") throw new Error(res.message);
83|    left -= 1;
84|    if (left <= 0) throw new Error(MSG_RETRY);
85|    await new Promise((done) => setTimeout(done, POLL_MS));
86|  }
87|}
88|
89|export function usePictures({
90|  bookId,
91|  textVersion,
92|  sceneId,
93|  pref,
94|}: {
95|  bookId: string;
96|  textVersion: string;
97|  sceneId: string;
98|  pref: ImageStylePref;
99|}) {
100|  const [card, setCard] = useState<SceneCard>(() => {
101|    const hit = sceneCache.get(sceneId);
102|    return hit ? { phase: "ready", url: hit.url, caption: hit.caption } : { phase: "idle" };
103|  });
104|  const [figures, setFigures] = useState<InlineFigure[]>(() =>
105|    (figureCache.get(sceneId) ?? []).filter((f) => f.phase !== "loading"),
106|  );
107|  const [popover, setPopover] = useState<{ top: number; left: number } | null>(null);
108|  const [lightbox, setLightbox] = useState<LightboxItem | null>(null);
109|  const viewRef = useRef<HTMLDivElement | null>(null);
110|  const popRef = useRef<HTMLButtonElement | null>(null);
111|  const openerRef = useRef<HTMLElement | null>(null);
112|  const busyRef = useRef(false);
113|  const prefRef = useRef(pref);
114|  prefRef.current = pref;
115|
116|  const hidePopover = useCallback(() => setPopover(null), []);
117|
118|  const storeFigures = useCallback(
119|    (next: InlineFigure[] | ((prev: InlineFigure[]) => InlineFigure[])) => {
120|      setFigures((prev) => {
121|        const value = typeof next === "function" ? (next as (p: InlineFigure[]) => InlineFigure[])(prev) : next;
122|        figureCache.set(sceneId, value);
123|        return value;
124|      });
125|    },
126|    [sceneId],
127|  );
128|
129|  const openLightbox = useCallback((src: string, caption: string, opener: HTMLElement | null) => {
130|    openerRef.current = opener;
131|    setLightbox({ src, caption });
132|  }, []);
133|
134|  const closeLightbox = useCallback(() => {
135|    setLightbox(null);
136|    openerRef.current?.focus?.();
137|    openerRef.current = null;
138|  }, []);
139|
140|  const illustrateScene = useCallback(() => {
141|    if (!canIllustrateScene({ sceneId, busy: busyRef.current, cached: sceneCache.has(sceneId) })) return;
142|    if (!tryStart(busyRef)) return;
143|    setPopover(null);
144|    setCard({ phase: "loading" });
145|    void poll({ kind: "scene", bookId, textVersion, sceneId, ...requestStyleFields(prefRef.current) })
146|      .then(({ url, caption }) => {
147|        sceneCache.set(sceneId, { url, caption });
148|        setCard({ phase: "ready", url, caption });
149|      })
150|      .catch((err: unknown) => {
151|        setCard({ phase: "error", message: err instanceof Error ? err.message : MSG_FAILED });
152|      })
153|      .finally(() => {
154|        finish(busyRef);
155|      });
156|  }, [bookId, textVersion, sceneId]);
157|
158|  const clearScene = useCallback(() => {
159|    sceneCache.delete(sceneId);
160|    setCard({ phase: "idle" });
161|  }, [sceneId]);
162|
163|  const requestFigure = useCallback(
164|    (id: string, startN: number, quote: string) => {
165|      // Callers acquire the gate; this only starts the request.
166|      void poll({ kind: "passage", bookId, textVersion, n: startN, ...requestStyleFields(prefRef.current) })
167|        .then(({ url }) => {
168|          storeFigures((prev) =>
169|            prev.map((f) => (f.id === id ? { ...f, phase: "ready", url, message: null } : f)),
170|          );
171|        })
172|        .catch((err: unknown) => {
173|          storeFigures((prev) =>
174|            prev.map((f) =>
175|              f.id === id
176|                ? { ...f, phase: "error", message: err instanceof Error ? err.message : MSG_FAILED }
177|                : f,
178|            ),
179|          );
180|        })
181|        .finally(() => {
182|          finish(busyRef);
183|        });
184|    },
185|    [bookId, textVersion, storeFigures],
186|  );
187|
188|  const illustratePassage = useCallback(() => {
189|    const view = viewRef.current;
190|    const sel = window.getSelection();
191|    if (!view || !sel || !sel.rangeCount || !canStart(busyRef.current)) return;
192|    const quote = sel.toString().trim();
193|    if (quote.length < 3) return;
194|    const entries: ParaEntry[] = [...view.querySelectorAll("p[id][data-n]")].map((el) => ({
195|      id: el.id,
196|      n: Number(el.getAttribute("data-n")),
197|    }));
198|    const startN = pickStartN(entries, paraOf(sel.anchorNode)?.id ?? null, paraOf(sel.focusNode)?.id ?? null);
199|    const endN = pickEndN(entries, paraOf(sel.anchorNode)?.id ?? null, paraOf(sel.focusNode)?.id ?? null);
200|    if (startN === null || endN === null) return;
201|    if (!tryStart(busyRef)) return;
202|    setPopover(null);
203|    sel.removeAllRanges();
204|    const id = `f${figureSeq++}`;
205|    const credit = styleCredit(requestStyleFields(prefRef.current));
206|    storeFigures((prev) => [
207|      ...prev,
208|      { id, phase: "loading", url: null, quote, startN, endN, credit, message: null },
209|    ]);
210|    requestFigure(id, startN, quote);
211|  }, [requestFigure, storeFigures]);
212|
213|  const retryFigure = useCallback(
214|    (id: string) => {
215|      const found = figureCache.get(sceneId)?.find((f) => f.id === id);
216|      if (!canRetryFigure(found, busyRef.current)) return;
217|      if (!tryStart(busyRef)) return;
218|      storeFigures((prev) => prev.map((f) => (f.id === id ? { ...f, phase: "loading", message: null } : f)));
219|      requestFigure(id, found.startN, found.quote);
220|    },
221|    [requestFigure, storeFigures, sceneId],
222|  );
223|
224|  const removeFigure = useCallback(
225|    (id: string) => {
226|      storeFigures((prev) => prev.filter((f) => f.id !== id));
227|    },
228|    [storeFigures],
229|  );
230|
231|  useEffect(() => {
232|    const view = viewRef.current;
233|    if (!view) return;
234|    let frame = 0;
235|    const onMouseUp = () => {
236|      cancelAnimationFrame(frame);
237|      frame = requestAnimationFrame(() => {
238|        const sel = window.getSelection();
239|        const text = sel?.toString().trim() ?? "";
240|        if (!sel || sel.isCollapsed || text.length < 3 || !sel.rangeCount) {
241|          setPopover(null);
242|          return;
243|        }
244|        if (!view.contains(sel.anchorNode) || !view.contains(sel.focusNode)) {
