1|// Picture state for one scene: the pane card plus inline figures.
2|// The client sends ordinals and ids only, never text. Session caches
3|// survive sub-page and scene moves, so a shown picture never refetches.
4|//
5|// Ordering rules: one request at a time across scene and figure (a second
6|// request while one is in flight is a silent no-op); retryFigure only
7|// works from the error phase; the caller must call hidePopover on pager
8|// moves. The style pref arrives as a hook argument and is read through a
9|// ref, so the callbacks stay stable when it changes.
10|"use client";
11|
12|import { useCallback, useEffect, useRef, useState } from "react";
13|import { MSG_FAILED, MSG_RETRY } from "@/core/images";
14|import { canIllustrateScene, canRetryFigure, canStart, finish, tryStart } from "./figure-placement";
15|import type { ImageResponse } from "@/core/images";
16|import { requestStyleFields, styleCredit } from "../image-style";
17|import type { ImageStylePref } from "../image-style";
18|import { pickEndN, pickStartN } from "../picture-selection";
19|import type { ParaEntry } from "../picture-selection";
20|
21|export type SceneCard =
22|  | { phase: "idle" }
23|  | { phase: "loading" }
24|  | { phase: "ready"; url: string; caption: string }
25|  | { phase: "error"; message: string };
26|
27|export interface InlineFigure {
28|  id: string;
29|  phase: "loading" | "ready" | "error";
30|  url: string | null;
31|  quote: string;
32|  startN: number;
33|  endN: number;
34|  credit: string;
35|  message: string | null;
36|}
37|
38|export interface LightboxItem {
39|  src: string;
40|  caption: string;
41|}
42|
43|const POLL_MS = 3000;
44|const POLL_MAX = 40;
45|
46|const sceneCache = new Map<string, { url: string; caption: string }>();
47|
48|// Read-only view of the session cache for the panels grid. Never
49|// writes, so it cannot change picture behaviour.
50|export function getCachedScenePicture(sceneId: string): { url: string; caption: string } | null {
51|  const hit = sceneCache.get(sceneId);
52|  return hit ? { url: hit.url, caption: hit.caption } : null;
53|}
54|const figureCache = new Map<string, InlineFigure[]>();
55|let figureSeq = 1;
56|
57|function paraOf(node: Node | null): Element | null {
58|  if (!node) return null;
59|  const el = node.nodeType === Node.TEXT_NODE ? node.parentElement : (node as Element);
60|  return el?.closest?.("p[id]") ?? null;
61|}
62|
63|async function postImage(body: unknown): Promise<ImageResponse> {
64|  const res = await fetch("/api/images", {
65|    method: "POST",
66|    headers: { "Content-Type": "application/json" },
67|    body: JSON.stringify(body),
68|  });
69|  return (await res.json()) as ImageResponse;
70|}
71|
72|async function poll(body: unknown): Promise<{ url: string; caption: string }> {
73|  let left = POLL_MAX;
74|  for (;;) {
75|    let res: ImageResponse;
76|    try {
77|      res = await postImage(body);
78|    } catch {
79|      throw new Error(MSG_FAILED);
80|    }
81|    if (res.status === "ready") return { url: res.url, caption: res.caption };
82|    if (res.status === "error") throw new Error(res.message);
83|    left -= 1;
84|    if (left <= 0) throw new Error(MSG_RETRY);
85|    await new Promise((done) => setTimeout(done, POLL_MS));
86|  }
87|}
88|
89|export function usePictures({
90|  bookId,
91|  textVersion,
92|  sceneId,
93|  pref,
94|}: {
95|  bookId: string;
96|  textVersion: string;
97|  sceneId: string;
98|  pref: ImageStylePref;
99|}) {
100|  const [card, setCard] = useState<SceneCard>(() => {
101|    const hit = sceneCache.get(sceneId);
102|    return hit ? { phase: "ready", url: hit.url, caption: hit.caption } : { phase: "idle" };
103|  });
104|  const [figures, setFigures] = useState<InlineFigure[]>(() =>
105|    (figureCache.get(sceneId) ?? []).filter((f) => f.phase !== "loading"),
106|  );
107|  const [popover, setPopover] = useState<{ top: number; left: number } | null>(null);
108|  const [lightbox, setLightbox] = useState<LightboxItem | null>(null);
109|  const viewRef = useRef<HTMLDivElement | null>(null);
